insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p66', 'allemand', '3AS', 12, 66, 'L3 3AS p66 — Fotos : Gutenbergs Werkstatt + Die aktuelle Druckerpresse', E'Fotos : Gutenbergs Werkstatt · Die aktuelle Druckerpresse', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p67', 'allemand', '3AS', 12, 67, 'L3 3AS p67 — Zum Schreiben : Ihre Zukunft (4 Themen) + « Der Computer hat die Welt revolutioniert » (6 Stichpunkte) + Erfindung', E'Zum Schreiben\n1. Wie sehen Sie Ihre Zukunft ? Wählen Sie ein Thema und schreiben Sie dazu einige Zeilen. (Gruppenarbeit)\nIhre eigene Zukunft · Leben auf anderen Planeten · Medizin/Gesundheit · Wirtschaft\n2. Man sagt : «Der Computer hat die Welt revolutioniert ?» Inwiefern ? Schreiben Sie anhand dieser Stichpunkte ein paar Zeilen :\n- Bessere Lebens- und Arbeitsbedingungen.\n- Komplizierte nervenaufreibende Arbeiten besser und schneller verrichten.\n- Abnehmen von anstrengenden und körperlichen Arbeiten.\n- Arbeitsvorgänge beschleunigen und rationalisieren.\n- Gefährliche und gesundheitsschädliche Aufgaben übernehmen.\n- Bessere Informations- und Kommunikationsmöglichkeiten ……\n3. Welche Erfindung hat Sie besonders beeindruckt ? Warum ?\nFotos : Rover auf dem Mars · Chirurgen im Operationssaal', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p68', 'allemand', '3AS', 12, 68, 'L3 3AS p68 — Informationen : Deutsches Museum (Haus der Superlative · 50.000 m² · Verkehrszentrum · Flugwerft)', E'Informationen\nDeutsches Museum\nSegelschiffe, Atommodelle, Windmühlen, Raumsonden, Dieselloks, Industrieroboter, Orgeln, Seenotkreuzer, …\nDiese unglaubliche Fülle an technischen Wundern - und vieles mehr- findet sich im Deutschen Museum. Ein Haus der Superlative : Es ist nicht nur eines der ersten naturwissenschaftlich-technischen Museen der Welt, sondern auch eines der meistbesuchtesten und mit 50.000 Quadratmeter Fläche eines der größten überhaupt.\nNaturgesetze, Instrumente und technische Verfahren werden in diesem Wissens-Olymp auf wissenschaftlich hohem Niveau und zugleich packend unterhaltsam präsentiert. Maschinen surren, Blitze zucken durch die Luft, Fernrohre zoomen Sternenwelten heran.\nDurch Greifen begreifen - das Konzept begeistert jährlich über 1 Million Menschen. Und es verhilft den Besuchern seit hundert Jahren zu einem umfassenden Grundverständnis von Wissenschaft und Technik.\nEbenfalls zum Deutschen Museum gehören das seit 2003 neu eröffnete Verkehrszentrum in den alten Messenhallen sowie die Flugwerft Oberschleißheim mit zahlreichen Flugzeugen.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p69', 'allemand', '3AS', 12, 69, 'L3 3AS p69 — Wortschatz L3 (18 Substantive · 10 Adjektive · Adverbien · Funktionswörter · 15 Verben)', E'Wortschatz\nSubstantive : s All · e Angst vor + Dativ · e Arbeitskraft(¨e) · r Arbeitsunternehmer(-) · r Arbeitsvertrag(¨e) · e Bequemlichkeit · e Daten · e Druckerpresse(n) · e Entscheidung · r Erfinder(-) · r Fortschritt(e) · r Gewinn · e Grundlage(n) · e Hoffnung(en) · s Interesse(n) · e Presse(n) · e Raumstation(en) · r Satellit(en) · e Sicherheit\nAdjektive : anstrengend · effizient · gefährlich · gehorsam · hartnäckig · hektisch · leichtfertig · sorglos · unbedacht · zuverlässig\nAdverbien : überhaupt · von außen\nFunktionswörter : ehe · während\nVerben : ab/nehmen (jdm etwas) · behalten · beschleunigen · dienen + Dativ · drucken · entscheiden · erfinden · heraus/finden · speichern · übernehmen · verleiten zu + Dativ · vernachlässigen · verpflanzen · verschwenden · widersprechen', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
